// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.deal(address(c), amount);
        vm.prank(nonOwner);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
